import { describe, expect, it } from 'vitest'

import fixture from '../test/debit-window.json'
import { actualDebitDate, lastBusinessDayOnOrBefore, nextBusinessDayOnOrAfter } from './debitDate'

/**
 * The A.C.B. run window, held to the server's own answer — cell by cell.
 *
 * `src/test/debit-window.json` is GENERATED by the server from its `DebitWindow` and copied here
 * unchanged (the merged gate compares the two copies byte for byte). Every month from 2026-01 to
 * 2027-12, in two holiday sets, every debit day 20 to 31: 576 cells. This file asserts that
 * `debitDate.js` — what the capture screen tells an administrator — lands on the same day as the
 * run the server prepares. Two implementations of one rule, compared against ONE artefact, never
 * against each other.
 *
 * The rule's direction is contested (question 33: SASBO's July file moved a Saturday forward; the
 * specification both repositories run moves it back). The fixture names the rule it encodes, and
 * the first test pins that name — so the day the server's rule flips, this file goes red and says
 * which half has not moved.
 */

const { rule, window: range, holidaySets, months } = fixture
const DAYS = Array.from({ length: range.lastDay - range.firstDay + 1 }, (_, i) => range.firstDay + i)

const holidaysOf = (set) => new Set(holidaySets[set].dates)
const firstOf = (month) => {
  const [y, m] = month.split('-').map(Number)
  return new Date(y, m - 1, 1)
}

/** Every cell where `compute` disagrees with the fixture, as readable strings. */
const disagreements = (compute) => {
  const found = []
  for (const row of months) {
    const holidays = holidaysOf(row.set)
    DAYS.forEach((day, i) => {
      const got = compute(day, firstOf(row.month), holidays)
      if (got !== row.days[i]) found.push(`${row.month} ${row.set} day ${day}: fixture ${row.days[i]}, got ${got}`)
    })
  }
  return found
}

const clientRule = (day, reference, holidays) => {
  const result = actualDebitDate(day, reference, holidays)
  // A result in another month would be a different answer, whatever its day number.
  return result && result.iso.startsWith(toMonth(reference)) ? result.day : null
}
const toMonth = (date) => `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}`

describe('debitDate.js against the server-generated window fixture', () => {
  it('the fixture encodes the rule this file implements -- backward in the month, forward only below the 20th', () => {
    expect(rule).toBe('backward-in-month-forward-below-20th')
    expect(range).toEqual({ firstDay: 20, lastDay: 31 })
  })

  it('the fixture is the whole domain: 24 months in two holiday sets, twelve days each', () => {
    // A comparison over an empty or truncated fixture would pass having compared nothing.
    expect(months).toHaveLength(48)
    expect(new Set(months.map((row) => row.set))).toEqual(new Set(['weekends-only', 'za-statutory']))
    expect(months.every((row) => row.days.length === DAYS.length)).toBe(true)
    expect(holidaySets['za-statutory'].dates.length).toBeGreaterThan(20)
  })

  it('every one of the 576 cells: the client lands on the day the server prepares', () => {
    expect(disagreements(clientRule)).toEqual([])
  })

  it('canary: a forward-first rule disagrees with the fixture -- the comparison can fail', () => {
    // The reading SASBO's July file suggests (question 33). If it matched every cell, the test
    // above would prove nothing about which reading is implemented.
    const forwardFirst = (day, reference, holidays) => {
      const month = reference.getMonth()
      const end = new Date(reference.getFullYear(), month + 1, 0).getDate()
      const target = new Date(reference.getFullYear(), month, Math.min(day, end))
      const forward = nextBusinessDayOnOrAfter(target, holidays)
      return (forward.getMonth() === month ? forward : lastBusinessDayOnOrBefore(target, holidays)).getDate()
    }
    const found = disagreements(forwardFirst)
    expect(found.length).toBeGreaterThan(0)
    // Witness W6: Saturday 25 July 2026 -- backward to Friday the 24th, forward to Monday the 27th.
    expect(found).toContain('2026-07 weekends-only day 25: fixture 24, got 27')
  })
})
